; Direction deltas, indexed by 1 up, 2 down, 3 left, 4 right.
; dir 0 is unused; dir_rev maps a direction to its opposite.
.org 0x678
pac_dc:
    .word 0, 0, 0, -1, 1
pac_dr:
    .word 0, -1, 1, 0, 0
pac_rev:
    .word 0, 2, 1, 4, 3

